/** Actual client packets, native capture, shared containers and four physical workers; reopened in a new JVM. */
public final class BuilderVisualCheck {
    private static final BlockPos SOURCE=new BlockPos(218,-57,120),BASE=new BlockPos(236,-57,108),DEST=new BlockPos(240,-57,120);
    private static volatile UUID resident,schema,job;
    private static volatile boolean reserveStocked;
    private static volatile boolean captured,partial,setupReady;private static boolean setupStarted;
    private static boolean finished,flightCaptured;private static int flightSeen=-1;private static int phase,age,total;private static int paperSlot, hireScreenWait;
    public static boolean done(){return finished;}
    private static void check(boolean b,String m){if(!b)throw new IllegalStateException("Builder visual: "+m);}
    private static ServerPlayer player(Minecraft mc){return mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());}
    private static EmploymentData.Station station(ServerLevel l,int i){return ((WorkBlockEntity)l.getBlockEntity(BASE.east(i*10))).station();}
    private static void capture(Minecraft mc,String name){Screenshot.grab(new File("../build"),"visual-builder-"+name+".png",mc.getMainRenderTarget(),m->{});}
    private static void click(Minecraft mc,String text){var b=mc.screen.children().stream().filter(x->x instanceof Button).map(x->(Button)x).filter(x->x.getMessage().getString().contains(text)).min(Comparator.comparingInt(x->x.getMessage().getString().equals(text)?0:1)).orElseThrow(()->new IllegalStateException("Builder button missing "+text));check(b.active,"Disabled "+text);b.onPress();}
    private static void server(Minecraft mc,java.util.function.Consumer<ServerPlayer> action){mc.getSingleplayerServer().execute(()->action.accept(player(mc)));}
    private static void use(Minecraft mc,BlockPos pos){mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false));}
    private static void next(){phase++;age=0;}
    private static void setup(ServerPlayer p){var l=p.getLevel();l.setDayTime(1000);l.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DOMOBSPAWNING).set(false,l.getServer());l.setWeatherParameters(10000,0,false,false);p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.teleportTo(l,238.5,-57,112.5,0,15);p.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.NIGHT_VISION,6000,0,false,false));
        for(int x=205;x<=320;x++)for(int z=80;z<=145;z++){l.setBlock(new BlockPos(x,-58,z),Blocks.STONE.defaultBlockState(),3);for(int y=-57;y<=-52;y++)l.setBlock(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState(),3);}
        for(int i=0;i<6;i++){var post=BASE.east(i*10);var home=post.offset(-2,0,-4);ResidenceData.get(l).unlinkAll(l,l.dimension(),home);l.setBlock(home,ResidenciasDosAldeoes.ANCHOR.get().defaultBlockState(),3);((br.com.residenciasaldeoes.block.ResidentialAnchorBlockEntity)l.getBlockEntity(home)).setSize(11);l.setBlock(home.south(),ResidenciasDosAldeoes.EMERALD_CHEST.get().defaultBlockState().setValue(ChestBlock.FACING,Direction.SOUTH),3);
            var bed=post.offset(-2,0,-2);var bs=Blocks.RED_BED.defaultBlockState().setValue(BedBlock.FACING,Direction.EAST);l.setBlock(bed,bs.setValue(BedBlock.PART,net.minecraft.world.level.block.state.properties.BedPart.FOOT),3);l.setBlock(bed.east(),bs.setValue(BedBlock.PART,net.minecraft.world.level.block.state.properties.BedPart.HEAD),3);
            var v=EntityType.VILLAGER.create(l);v.setAge(0);v.setNoAi(true);v.setPos(post.getX()+.5,post.getY(),post.getZ()+1.5);l.addFreshEntity(v);check(ResidenceData.get(l).link(l,home,v).equals("ok"),"home "+i);ResidenceData.get(l).renameResident(v.getUUID(),"Construtor "+i);l.setBlock(post,WorkModule.BUILDER.get().defaultBlockState(),3);var s=station(l,i);s.setItem(31,new ItemStack(Items.EMERALD,30));if(i==0)resident=v.getUUID();else{p.teleportTo(l,post.getX()+.5,post.getY(),post.getZ()+2.5,180,15);check(Employment.hire(p,s,v.getUUID(),Profession.BUILDER).equals("ok"),"hire "+i);WorkforceData.get(l).setProgress(v.getUUID(),Profession.BUILDER.id(),1,0);}}
        for(var at:BlockPos.betweenClosed(SOURCE,SOURCE.offset(2,0,2)))l.setBlock(at,Blocks.STONE.defaultBlockState(),3);l.setBlock(SOURCE.above(),Blocks.OAK_STAIRS.defaultBlockState().setValue(StairBlock.FACING,Direction.EAST),3);l.setBlock(SOURCE.offset(1,1,0),Blocks.OAK_PLANKS.defaultBlockState(),3);l.setBlock(SOURCE.offset(2,1,0),Blocks.GLASS.defaultBlockState(),3);l.setBlock(SOURCE.offset(1,1,1),Blocks.CHEST.defaultBlockState(),3);((ChestBlockEntity)l.getBlockEntity(SOURCE.offset(1,1,1))).setItem(0,new ItemStack(Items.DIAMOND,7));l.setBlock(SOURCE.offset(2,1,2),Blocks.GLASS.defaultBlockState(),3);

        var d=BuilderData.get(l);d.stock.clearContent();d.library.clear();d.jobs.clear();d.papers.clear();d.ink=d.charge=d.printTicks=d.printPaid=0;d.printing=null;d.stock.setItem(0,new ItemStack(Items.STONE,64));d.stock.setItem(1,new ItemStack(Items.OAK_STAIRS));d.stock.setItem(2,new ItemStack(Items.OAK_PLANKS));d.stock.setItem(3,new ItemStack(Items.GLASS,2));d.stock.setItem(27,new ItemStack(Items.INK_SAC,15));d.stock.setItem(28,new ItemStack(Items.EMERALD,15));d.stock.setItem(29,new ItemStack(BuilderModule.BLANK.get(),3));d.refill();p.teleportTo(l,BASE.getX()+.5,BASE.getY(),BASE.getZ()+2.5,180,15);clearHostiles(l);WorkBlock.open(p,station(l,0));setupReady=true;
    }
    public static void tick(Minecraft mc,int unused){total++;if(phase==0&&(!setupReady||!(mc.screen instanceof WorkScreen))&&!setupStarted){setupStarted=true;mc.getTutorial().setStep(net.minecraft.client.tutorial.TutorialSteps.NONE);mc.getToasts().clear();server(mc,BuilderVisualCheck::setup);}if(phase==0&&!setupReady){age=0;return;}age++;check(total<2400,"fixture timed out phase "+phase);switch(phase){
        case 0->{if(age==20)server(mc,p->clearHostiles(p.getLevel()));if(age==30){check(mc.screen instanceof WorkScreen,"hiring screen");String id=resident.toString().substring(0,6);for(int i=0;i<100&&mc.screen.children().stream().noneMatch(x->x instanceof Button b&&b.getMessage().getString().contains(id));i++)click(mc,">");click(mc,id);click(mc,"Construtor");}if(age==35)capture(mc,"hiring");if(age==40){server(mc,p->p.getInventory().setItem(9,new ItemStack(Items.EMERALD,10)));click(mc,"Contratar");}if(age==48)PaymentVisualCheck.fund(mc,9);if(age==54)PaymentVisualCheck.confirm(mc,10,1);if(age==65){
            if(!(mc.screen instanceof BuilderScreen)&&hireScreenWait++<100){age=64;return;}
            check(mc.screen instanceof BuilderScreen,"professional screen");check(mc.screen.children().stream().anyMatch(widget->widget instanceof Button button&&button.getMessage().getString().equals("Demitir")),"Builder dismissal button missing");server(mc,p->{var l=p.getLevel();var s=station(l,0);check(s.worker.equals(resident)&&s.getItem(31).getCount()==30,"legacy post balance was changed by payment");WorkforceData.get(l).setProgress(resident,Profession.BUILDER.id(),1,0);var d=BuilderData.get(l);check(d.ink==1000&&d.charge==500&&d.stock.getItem(27).getCount()==5&&d.stock.getItem(28).getCount()==10,"15 ink / 15 emerald example");});capture(mc,"global");}if(age==75){mc.player.closeContainer();server(mc,p->{p.teleportTo(p.getLevel(),BASE.getX()+50.5,-57,BASE.getZ()+2.5,180,15);WorkBlock.open(p,station(p.getLevel(),5));});}if(age==100){if(!(mc.player.containerMenu instanceof BuilderMenu m)||!m.pos.equals(BASE.east(50))||m.snapshot.isEmpty()||m.stock.getItem(0).isEmpty()){age=99;return;}check(m.stock.getItem(0).getCount()==64&&m.snapshot.getInt("ink")==1000&&m.snapshot.getInt("charge")==500,"50 blocks global sharing");capture(mc,"global-fifty");mc.player.closeContainer();server(mc,p->{p.teleportTo(p.getLevel(),220.5,-57,124.5,180,25);p.getInventory().setItem(0,new ItemStack(BuilderModule.ENGINEER.get()));p.getInventory().selected=0;});}if(age==120){mc.player.getInventory().selected=0;use(mc,SOURCE);}if(age==130)use(mc,SOURCE.offset(2,1,2));if(age==145){check(mc.screen instanceof BlueprintEditorScreen,"engineer editor");for(var w:mc.screen.children())if(w instanceof EditBox e)e.setValue("Casa Cooperativa");capture(mc,"capture");click(mc,"Salvar seleção");}if(age>150&&age%10==0)server(mc,p->{var d=BuilderData.get(p.getLevel());var b=d.library.values().stream().filter(x->x.name.equals("Casa Cooperativa")).findFirst().orElse(null);if(b!=null){check(b.cells.size()==14&&!b.save().toString().contains("diamond"),"capture size/privacy");schema=b.id;captured=true;}});if(captured){server(mc,p->{p.teleportTo(p.getLevel(),BASE.getX()+.5,-57,BASE.getZ()+2.5,180,15);WorkBlock.open(p,station(p.getLevel(),0));});System.out.println("BUILDER_CAPTURE_AND_GLOBAL_STOCK_PASSED");next();}}
        case 1->{if(age==25)click(mc,"Casa Cooperativa");if(age==35)click(mc,"Materiais");if(age==45){capture(mc,"materials");click(mc,"Voltar");}if(age==55)click(mc,"Gravar");if(age==95)capture(mc,"print");if(age==175){
            check(mc.player.containerMenu instanceof BuilderMenu,"print menu closed early");
            var menu=(BuilderMenu)mc.player.containerMenu;
            // Printing uses integrated server ticks, while this fixture counts client ticks.
            // Wait within the existing fixture deadline for the synchronized output.
            if(!menu.stock.getItem(30).is(BuilderModule.PAPER.get())){age=174;return;}
            check(!menu.stock.getItem(30).hasFoil(),"printed paper");
            mc.gameMode.handleInventoryMouseClick(menu.containerId,30,0,net.minecraft.world.inventory.ClickType.QUICK_MOVE,mc.player);
        }if(age==190){mc.player.closeContainer();paperSlot=-1;for(int i=0;i<9;i++)if(mc.player.getInventory().getItem(i).is(BuilderModule.PAPER.get()))paperSlot=i;check(paperSlot>=0,"paper in hotbar");mc.player.getInventory().selected=paperSlot;server(mc,p->p.teleportTo(p.getLevel(),238.5,-57,125.5,200,25));}if(age==205)use(mc,DEST.below());if(age==220){check(mc.screen instanceof BlueprintEditorScreen&&BuilderClient.previewCells()==14,"native block hologram");click(mc,"X+");click(mc,"Alt.+");click(mc,"Alt.−");click(mc,"Girar");click(mc,"Espelhar");}if(age==240)capture(mc,"hologram");if(age==245)click(mc,"Confirmar posição");if(age==260){check(mc.player.getMainHandItem().hasFoil(),"confirmed paper foil");server(mc,p->{p.teleportTo(p.getLevel(),BASE.getX()+.5,-57,BASE.getZ()+2.5,180,15);WorkBlock.open(p,station(p.getLevel(),0));});}if(age==280){var m=mc.player.containerMenu;int index=60+paperSlot;check(m.getSlot(index).getItem().is(BuilderModule.PAPER.get()),"hotbar menu index");mc.gameMode.handleInventoryMouseClick(m.containerId,index,0,net.minecraft.world.inventory.ClickType.QUICK_MOVE,mc.player);}if(age==300){check(mc.player.containerMenu instanceof BuilderMenu m&&m.snapshot.getBoolean("planValid"),"confirmed plan sync");click(mc,"Construir");}if(age==315){mc.player.closeContainer();server(mc,p->{var l=p.getLevel();var d=BuilderData.get(l);var j=d.jobs.values().stream().filter(x->d.papers.get(x.paper).schema.equals(schema)).findFirst().orElseThrow();job=j.id;for(int i=0;i<6;i++)((Villager)l.getEntity(station(l,i).worker)).setNoAi(false);p.getAbilities().flying=true;p.onUpdateAbilities();p.teleportTo(l,242.5,-53,129.5,180,32);});System.out.println("BUILDER_PRINT_AND_POSITION_PASSED");next();}}
        case 2->{observeFlight(mc,total);if(age%5==0&&!partial)server(mc,p->{var l=p.getLevel();var d=BuilderData.get(l);var j=d.jobs.get(job);check(j!=null&&j.workers.size()<=6&&j.workers.values().stream().filter(x->x>=0).count()<=4,"worker capacity");if(age%100==0)System.out.println("BUILDER_DEBUG done="+j.done.cardinality()+" roles="+j.workers+" tasks="+j.tasks.size()+" "+j.status);if(j.workers.values().stream().filter(x->x>=0).count()==4&&j.done.cardinality()>=4&&j.done.cardinality()<14&&j.tasks.size()>=4&&j.tasks.values().stream().filter(task->task.lastActive>=l.getGameTime()-12).count()==4){j.paused=true;j.status="Pausa solicitada para teste de reinicialização.";var s=station(l,0);s.industry.putUUID("visual_builder_job",j.id);var reserve=j.workers.entrySet().stream().filter(e->e.getValue()<0).findFirst().orElseThrow().getKey();var barrelPos=EmploymentData.get(l).assigned(reserve).pos.south(3);l.setBlock(barrelPos,Blocks.BARREL.defaultBlockState(),3);((BarrelBlockEntity)l.getBlockEntity(barrelPos)).setItem(1,new ItemStack(Items.DIRT,64));s.industry.putLong("visual_builder_barrel",barrelPos.asLong());s.industry.putInt("visual_builder_done",j.done.cardinality());s.industry.putInt("visual_builder_charge",d.charge);s.industry.putLong("visual_builder_xp",xp(l));s.setChanged();d.setDirty();partial=true;System.out.println("BUILDER_FOUR_WORKERS_AND_FLIGHT_PASSED");}});if(age%15==0)capture(mc,"cooperative");if(partial){check(flightCaptured,"no visible block flight");System.out.println("BUILDER_PARTIAL_PROJECT_SAVED");finished=true;next();}}
        default->{}
    }}
    private static void observeFlight(Minecraft mc,int tick){if(flightCaptured)return;if(BuilderClient.flyingBlocks()==0){flightSeen=-1;return;}if(flightSeen<0)flightSeen=tick;if(tick-flightSeen>=6){capture(mc,"flight");flightCaptured=true;}}
    private static long xp(ServerLevel l){long n=0;for(int i=0;i<6;i++)n+=WorkforceData.get(l).progress(station(l,i).worker,Profession.BUILDER.id()).xp();return n;}
    private static void clearHostiles(ServerLevel l){l.getEntitiesOfClass(net.minecraft.world.entity.Mob.class,new AABB(200,-64,75,330,-40,155),e->e instanceof net.minecraft.world.entity.monster.Enemy).forEach(net.minecraft.world.entity.Entity::discard);}
    public static void verifyRestore(ServerLevel l){clearHostiles(l);var d=BuilderData.get(l);var s=station(l,0);job=s.industry.getUUID("visual_builder_job");var j=d.jobs.get(job);check(j!=null&&j.paused&&j.done.cardinality()==s.industry.getInt("visual_builder_done")&&d.charge==s.industry.getInt("visual_builder_charge")&&xp(l)==s.industry.getLong("visual_builder_xp"),"partial receipt/timer/global/XP reloaded");check(d.ink==986&&d.stock.getItem(27).getCount()==5&&d.stock.getItem(28).getCount()==10&&d.stock.getItem(29).getCount()==2,"persistent print resources");System.out.println("BUILDER_WORLD_RESTART_PASSED");}
    public static void restoredTick(Minecraft mc,int tick){if(tick>170&&tick<1000)observeFlight(mc,tick);if(tick==160){mc.player.closeContainer();server(mc,p->{var l=p.getLevel();l.setDayTime(1000);p.getAbilities().flying=true;p.onUpdateAbilities();p.teleportTo(l,252.5,-53,122.5,180,32);var d=BuilderData.get(l);d.jobs.get(job).paused=false;d.setDirty();});}if(tick>160&&tick%10==0&&!reserveStocked)server(mc,p->{
        if(reserveStocked)return;
        var l=p.getLevel();
        var j=BuilderData.get(l).jobs.get(job);
        if(j.done.cardinality()!=13)return;
        var at=BlockPos.of(station(l,0).industry.getLong("visual_builder_barrel"));
        var barrel=(BarrelBlockEntity)l.getBlockEntity(at);
        check(j.workers.values().stream().filter(role->role>=0).count()==4,"four active building slots at resupply");
        check(j.workers.entrySet().stream().anyMatch(e->e.getValue()<0&&EmploymentData.get(l).assigned(e.getKey()).pos.south(3).equals(at)),"material belongs to an excess worker");
        barrel.setItem(0,new ItemStack(Items.CHEST));
        reserveStocked=true;
        System.out.println("BUILDER_13_BLOCKS_RESERVE_RESUPPLY_PASSED");
    });if(tick==1100)server(mc,p->{var l=p.getLevel();var d=BuilderData.get(l);var j=d.jobs.get(job);var b=d.library.get(d.papers.get(j.paper).schema);check(j.done.cardinality()==14&&j.placed==14&&d.charge==486&&xp(l)==14,"resumed placement/XP charged exactly once: done="+j.done.cardinality()+" placed="+j.placed+" charge="+d.charge+" XP="+xp(l)+" "+j.status);for(int i=0;i<b.cells.size();i++){var at=BuilderWork.target(b,j,i);check(BuilderWork.matches(l.getBlockState(at),BuilderWork.expected(b,j,i)),"rotated/mirrored world cell "+i);if(l.getBlockEntity(at) instanceof ChestBlockEntity chest)check(chest.isEmpty(),"private chest copied");}check(((ChestBlockEntity)l.getBlockEntity(SOURCE.offset(1,1,1))).getItem(0).getCount()==7,"capture modified source");var barrel=(BarrelBlockEntity)l.getBlockEntity(BlockPos.of(station(l,0).industry.getLong("visual_builder_barrel")));check(reserveStocked&&barrel.getItem(0).isEmpty()&&barrel.getItem(1).getCount()==64,"physical needed-only collection");check(d.stock.getItem(0).getCount()==55,"material debit");System.out.println("BUILDER_RESUMED_ONCE_PASSED");});if(tick==1110)server(mc,p->{p.teleportTo(p.getLevel(),BASE.getX()+.5,-57,BASE.getZ()+2.5,180,15);WorkBlock.open(p,station(p.getLevel(),0));});if(tick==1125){check(mc.player.containerMenu instanceof BuilderMenu,"restored global menu");var m=(BuilderMenu)mc.player.containerMenu;BuilderNetwork.CHANNEL.sendToServer(new BuilderNetwork.Command(m.containerId,m.stationId,4,job.toString()));}if(tick==1145){check(mc.screen instanceof BuilderScreen&&mc.player.containerMenu instanceof BuilderMenu m&&job.equals(m.selectedJob),"restored job selection packet");capture(mc,"progress-restored");System.out.println("BUILDER_PROGRESS_SCREEN_PASSED");}}
}
